// `m_atoms` is the number of 64-row M-atoms to actually issue for THIS tile —
// ceil(nrows/64), NOT the compile-time kAtomsM. The ragged LAST tile has
// nrows < kTileM (e.g. 64 < 128), so issuing the full kAtomsM would read X rows
// [nrows, kTileM) — addresses PAST this tile's valid data, overrunning into the
// adjacent activation buffer (or, for the trailing acts buffer, into the dW-
// partial/opt-reduce workspace tail). Those operands are uninitialized on the
// first launch (fresh cudaMalloc reads 0 → benign) but hold the PRIOR launch's
// scratch on every reuse — for Prodigy/Muon the P2.6/P2.7 stages leave large
// values there, so the over-read injects garbage and the bf16 wgmma blows the
// grad to ~1e20 → NaN on repeat (compute-sanitizer initcheck pins the read to
// dectc_gemm_fwd's srcA). The padding-row OUTPUTS were always unused (every
// consumer loops `nrows`), so clamping m_atoms drops only dead work and the
// valid-row results are BYTE-IDENTICAL — the already-green cells are unaffected.
template <int N>
__device__ __forceinline__ void dectc_gemm_fwd(
        const __nv_bfloat16* __restrict__ X, const float* __restrict__ W,
        __nv_bfloat16* __restrict__ Yout, int Kin, int Nout, int m_atoms,
        __nv_bfloat16* sA, __nv_bfloat16* sB) {
    const int k_steps = Kin / wgs::kWgmmaAtomK;
    for (int n0 = 0; n0 < Nout; n0 += N) {
        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
            int nn = n0 + n; return nn < Nout ? __float2bfloat16(W[(int64_t)nn * Kin + k]) : __float2bfloat16(0.f); };
        auto out  = [&] (int m, int n, float v) {
            Yout[(int64_t)m * Nout + n0 + n] = __float2bfloat16(v); };
        tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/kAtomsM>(
            0, m_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
    }
}

